static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var group=scene.GetRootGameObjects().Single(g=>g.name=="City Building Signs - Shared Atlas");var rs=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/CityBuildingSigns/City Shared Sign Atlas.mat");var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();var native=rs.Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()&&r.sharedMaterials.Any(m=>m&&m.name.StartsWith("Building"))).ToArray();var gt=T.GetNestedType("Geo",BindingFlags.NonPublic);var all=Array.CreateInstance(gt,native.Length);for(int i=0;i<native.Length;i++)all.SetValue(C("Read",native[i]),i);
var created=new List<Tuple<Vector3,Vector3>>();int banners=0;foreach(var f in group.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.Contains("Pedestrian bridge"))){created.Add(Tuple.Create(f.transform.position,f.sharedMesh.normals[24]));banners++;}
