log.AppendLine("Candidates="+candidates.Count);int supported=0;foreach(var s in candidates.OrderBy(c=>new Vector2(c.Item1.x+30.95f,c.Item1.z+285.89f).magnitude)){if(banners>=4)break;if(created.Any(c=>Vector3.Distance(c.Item1,s.Item1)<18))continue;float w=2.2f,h=.25f;var mid=s.Item1;object[] args={g,mid,s.Item2,w,h,0f};if(!(bool)E.GetMethod("Support",F).Invoke(null,args))continue;supported++;var center=mid+s.Item2*(float)args[5];object[] view={all,controller.streetLightPositions,center,s.Item2,Vector3.zero};if(!(bool)typeof(FinalCitySignsFinish).GetMethod("RoadView",F).Invoke(null,view))continue;
var replacement=group.transform.Cast<Transform>().Where(t=>t.name.StartsWith("Long facade column")&&!t.name.Contains("building43")).OrderBy(t=>t.GetComponent<MeshFilter>().sharedMesh.bounds.size.y).First();UnityEngine.Object.DestroyImmediate(replacement.gameObject);E.GetMethod("Banner",F).Invoke(null,new object[]{g,center,s.Item2,w,h,group.transform,mat,"Pedestrian bridge "+banners,banners});created.Add(Tuple.Create(center,s.Item2));log.AppendLine("Pedestrian bridge banner "+center+" normal="+s.Item2);banners++;}log.AppendLine("Supported="+supported);}
for(int i=0;i<created.Count;i++){var v=created[i];float advance=0;foreach(var r in rs.Where(r=>!r.transform.IsChildOf(group.transform)&&r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()&&r.bounds.SqrDistance(v.Item1)<36)){var gg=C("Read",r);object[] hit={gg,v.Item1+v.Item2*6,-v.Item2,Vector3.zero,Vector3.zero};if((bool)C("Hit",hit)){float d=Vector3.Dot((Vector3)hit[3]-v.Item1,v.Item2);if(d>0&&d<4)advance=Mathf.Max(advance,d+.15f);}}if(advance>0){var f=group.GetComponentsInChildren<MeshFilter>().First(x=>x.name.Contains("Pedestrian bridge")&&Vector3.Distance(x.transform.position,v.Item1)<.01f);f.transform.position+=v.Item2*advance;created[i]=Tuple.Create(f.transform.position,v.Item2);log.AppendLine("Cleared outer bridge skin="+advance);}}AssetDatabase.SaveAssets();PrefabUtility.SaveAsPrefabAssetAndConnect(group,"Assets/Scenes/Oasis/CityBuildingSigns/City Building Signs.prefab",InteractionMode.AutomatedAction);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
bool night=controller.IsNight;try{controller.ApplyDay();foreach(var f in group.GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("Long facade column")&&f.name.Contains("building43")).Take(2)){var p=f.transform.position;var mesh=f.sharedMesh;var normal=mesh.normals[24];object[] view={all,controller.streetLightPositions,p,normal,Vector3.zero};if((bool)typeof(FinalCitySignsFinish).GetMethod("RoadView",F).Invoke(null,view))Photo(scene,(Vector3)view[4],p,"Gold-Facade-"+f.name.Substring(19,3));}
for(int i=0;i<created.Count;i++){var s=created[i];object[] view={all,controller.streetLightPositions,s.Item1,s.Item2,Vector3.zero};Photo(scene,s.Item1+s.Item2*6-Vector3.up*.2f,s.Item1,"Pedestrian-Bridge-Signs-"+i);}
}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}var renderers=group.GetComponentsInChildren<MeshRenderer>(true);var master=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/CityBuildingSigns/City Building Signs.prefab");if(renderers.Length!=600||master.GetComponentsInChildren<MeshRenderer>(true).Length!=600||renderers.Any(r=>r.sharedMaterial!=mat)||group.GetComponentsInChildren<LODGroup>().Length!=600||group.GetComponentsInChildren<Light>().Length>0||group.GetComponentsInChildren<Collider>().Length>0)throw new Exception("Prefab/material/mobile checks failed");log.AppendLine("Scene/master=600; one shared material; 600 LOD groups; no lights/colliders; triangles="+renderers.Sum(r=>(int)r.GetComponent<MeshFilter>().sharedMesh.GetIndexCount(0)/3));if(group.transform.childCount!=600)throw new Exception("Count changed to "+group.transform.childCount);int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);log.AppendLine("SUCCESS total prefabs=600; additional pedestrian bridge banners="+banners+"; yellow building family building43 has facade-height columns; original atlas/material unchanged; shader errors=0");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/SignReferenceFinishReport.txt",log.ToString());}}
